cat << 'EOF' > generate_token.js
const jwt = require('jsonwebtoken');
const fs = require('fs');

const projectId = process.env.PARAGON_PROJECT_ID;
const signingKey = process.env.PARAGON_SIGNING_KEY.replace(/\\n/g, '\n');

const token = jwt.sign(
  {
    sub: 'test-user',
  },
  signingKey,
  {
    algorithm: 'RS256',
    expiresIn: '1h'
  }
);
console.log(token);
EOF
npm install jsonwebtoken
node generate_token.js

